import { Component, computed, input, output } from '@angular/core';
import { Tramite, ModalidadValue, NivelGobiernoValue } from '../../../../../shared/models/tramite.model';

const MODALIDAD_LABEL: Record<ModalidadValue, string> = {
  en_linea: 'En línea',
  presencial: 'Presencial',
};

const NIVEL_LABEL: Record<NivelGobiernoValue, string> = {
  estatal: 'Estatal',
  municipal: 'Municipal',
  federal: 'Federal',
};

@Component({
  selector: 'app-tramite-card',
  templateUrl: './tramite-card.component.html',
})
export class TramiteCardComponent {
  readonly tramite = input.required<Tramite>();
  readonly editar = output<number>();
  readonly eliminar = output<number>();

  protected readonly canalLabels = computed(() =>
    this.tramite().modalidad.map(m => MODALIDAD_LABEL[m] ?? m),
  );

  protected readonly nivelLabel = computed(() => NIVEL_LABEL[this.tramite().nivelGobierno] ?? this.tramite().nivelGobierno);
}
