import { Component, inject, signal, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { TramiteService } from '../../../../../shared/services/tramite.service';
import { Tramite, PaginatedTramites } from '../../../../../shared/models/tramite.model';
import { TramiteCardComponent } from './tramite-card.component';
import { PaginatorComponent } from '../../../../../shared/components/paginator/paginator.component';
import { extractErrorMessage } from '../../../../../shared/utils/error-utils';

@Component({
  selector: 'app-tramite-list',
  imports: [TramiteCardComponent, PaginatorComponent],
  templateUrl: './tramite-list.component.html',
})
export class TramiteListComponent implements OnInit {
  private readonly tramiteService = inject(TramiteService);
  private readonly router = inject(Router);

  protected readonly searchTerm = signal('');
  protected readonly sortBy = signal<'nombre' | 'created_at' | 'nivel_gobierno' | 'vigencia_dias'>('created_at');
  protected readonly sortOrder = signal<'asc' | 'desc'>('desc');
  protected readonly page = signal(1);
  protected readonly perPage = signal(15);

  protected readonly tramites = signal<Tramite[]>([]);
  protected readonly total = signal(0);
  protected readonly lastPage = signal(1);
  protected readonly loading = signal(false);

  ngOnInit(): void {
    this.loadTramites();
  }

  protected loadTramites(): void {
    this.loading.set(true);
    this.tramiteService
      .getTramites({
        search: this.searchTerm() || undefined,
        sortBy: this.sortBy(),
        sortOrder: this.sortOrder(),
        page: this.page(),
        perPage: this.perPage(),
      })
      .subscribe({
        next: (result: PaginatedTramites) => {
          this.tramites.set(result.data);
          this.total.set(result.total);
          this.lastPage.set(result.last_page);
          this.loading.set(false);
        },
        error: () => {
          this.loading.set(false);
        },
      });
  }

  protected onSearch(event: Event): void {
    const value = (event.target as HTMLInputElement).value;
    this.searchTerm.set(value);
    this.page.set(1);
    this.loadTramites();
  }

  protected onSort(field: 'nombre' | 'created_at' | 'nivel_gobierno' | 'vigencia_dias'): void {
    if (this.sortBy() === field) {
      this.sortOrder.set(this.sortOrder() === 'asc' ? 'desc' : 'asc');
    } else {
      this.sortBy.set(field);
      this.sortOrder.set('asc');
    }
    this.page.set(1);
    this.loadTramites();
  }

  protected onPageChange(page: number): void {
    this.page.set(page);
    this.loadTramites();
  }

  protected onPageSizeChange(size: number): void {
    this.perPage.set(size);
    this.page.set(1);
    this.loadTramites();
  }

  protected onNuevo(): void {
    this.router.navigate(['/ejecutivos/configuracion/tramites/nueva']);
  }

  protected onEditar(id: number): void {
    this.router.navigate(['/ejecutivos/configuracion/tramites', id, 'editar']);
  }

  protected onEliminar(id: number): void {
    if (!window.confirm('¿Estás seguro de eliminar este trámite?')) return;

    this.tramiteService.deleteTramite(id).subscribe({
      next: () => {
        this.loadTramites();
      },
      error: (err) => {
        window.alert(extractErrorMessage(err));
      },
    });
  }

  protected sortIcon(field: 'nombre' | 'created_at' | 'nivel_gobierno' | 'vigencia_dias'): string {
    if (this.sortBy() !== field) return '';
    return this.sortOrder() === 'asc' ? ' ▲' : ' ▼';
  }
}
